\begin{lemma}[Properties of outcome relabelling; formalization support]
	\label{lem:pasting-alphabet-relabelling}
	\lean{MIPStarRE.QPBT.Measurement.isProjective_congrAlphabet, MIPStarRE.QPBT.Measurement.postprocess_congrAlphabet}
	\leanok
	\uses{def:pasting-alphabet-relabelling, def:povm-conventions}
	Let $M$ be a POVM on a finite outcome set $\alpha$, let
	$e:\beta\to\alpha$ be a bijection, and write $N_b=M_{e(b)}$ for the
	relabelled POVM. If $M$ is projective, then $N$ is projective.
	For any map $f:\beta\to\gamma$ to a finite set and any $c\in\gamma$,
	\[
		N_{[f(\cdot)=c]}=M_{[f(e^{-1}(\cdot))=c]}.
	\]
\end{lemma}
\begin{proof}
	\leanok
	\uses{def:pasting-alphabet-relabelling, def:povm-conventions}
	Each effect of $N$ is an effect of $M$, so projectivity is preserved.
	Reindexing the sum over $\{b:f(b)=c\}$ by $e$ gives the stated
	postprocessing identity.
\end{proof}

\begin{lemma}[Formalization support for Lemma~\ref{lem:pasting}]
	\label{lem:pasting-tensor-placement}
	\lean{MIPStarRE.QPBT.Measurement.isProjective_leftPlacement, MIPStarRE.QPBT.Measurement.isProjective_rightPlacement, MIPStarRE.QPBT.Measurement.leftPlacement_postprocess, MIPStarRE.QPBT.Measurement.rightPlacement_postprocess}
	\leanok
	\uses{def:pasting-tensor-placement}
	This formalization-only auxiliary collects the properties of the placement
	used in Lemma~\ref{lem:pasting}. The placement of a projective measurement is
	projective, and the placement of a postprocessed measurement has the same effects as the
	postprocessing of the placed measurement.
\end{lemma}
\begin{proof}
	\leanok
	\uses{lem:distance-measurement-effect-hermitian}
	Projectivity follows from the multiplicativity of the placement together
	with the idempotence and self-adjointness of the effects. Compatibility with
	postprocessing is the additivity of the tensor placement applied to the sum
	of the effects over a fibre.
\end{proof}

