\begin{lemma}[Formalization support for Lemma~\ref{lem:pasting}]
	\label{lem:pasting-coarse-commutator}
	\lean{MIPStarRE.QPBT.exists_coarse_commutator_bound}
	\leanok
	\uses{def:pasting-alphabet-relabelling, lem:commutation-analysis-right,
		fact:agreement, def:povm-distance}
	In the setting of Lemma~\ref{lem:pasting}, write
	$P_{a_1} = (G_1)^x_{[\operatorname{eval}_{y_1}(\cdot)=a_1]}$ and
	$Q_{a_2} = (G_2)^x_{[\operatorname{eval}_{y_2}(\cdot)=a_2]}$ for the two
	coarse codeword families. There is a universal constant $C \ge 1$,
	independent of the finite sets, of the space, of the distribution, of the
	measurements, of the state and of the error, such that the two comparisons
	in \eqref{eq:pasting-1} give
	\[
		\Id \ot [P_{a_1},\, Q_{a_2}] \approx_{C \delta} 0\,.
	\]
\end{lemma}
\begin{proof}
	\leanok
	\uses{lem:commutation-analysis-right, fact:agreement,
		def:pasting-alphabet-relabelling, lem:pasting-alphabet-relabelling}
	The two comparisons bound the consistency of each coarse family with the
	idempotent, $A_{a_1} \ot [P_{a_1}, G_{g_2}] G_{g_2}
	= (A_{a_1} \ot [P_{a_1}, G_{g_2}]) (A_{a_1} \ot G_{g_2})$. The commutator is
	anti-self-adjoint, so the quadratic form of that product is the real part of
	the inner product of the two applied vectors, and the Cauchy--Schwarz
	inequality over the pairs $(a_1, g_2)$ bounds the difference by the product
	of the two square roots. The second factor is at most $1$, the operators
	$A_{a_1} \ot G_{g_2}$ being the effects of a measurement; in the first factor
	the answer effect is dropped, which leaves the square root of the commutator
	mass at that question. Jensen's inequality for the square root gives the
	averaged form.
\end{proof}

\begin{lemma}[Formalization support for Lemma~\ref{lem:pasting}]
	\label{lem:pasting-cross-move}
	\lean{MIPStarRE.QPBT.abs_cross_move_gap_le_sqrt}
	\leanok
	\uses{def:pasting-tensor-placement}
	Let $P_{a_1}$ and $G_{g_2}$ be measurements placed on the second tensor
	factor and let $\ket{\psi}$ be a unit vector. Then
	\[
		\Bigl| \operatorname{Re}\sum_{a_1, g_2}
			\bra{\psi} \Id \ot G_{g_2} P_{a_1} G_{g_2} P_{a_1}
			\ket{\psi} - \operatorname{Re}\sum_{g_2} \bra{\psi} G_{g_2} \ot \sum_{a_1} P_{a_1}
			G_{g_2} P_{a_1} \ket{\psi} \Bigr| \le \Bigl( \sum_{g_2} \bigl\|
			(\Id \ot G_{g_2} - G_{g_2} \ot \Id) \ket{\psi} \bigr\|^2
		\Bigr)^{1/2}\,.
	\]
\end{lemma}
\begin{proof}
	\leanok
	\uses{def:pasting-tensor-placement}
	Each summand on the left is the overlap of
	$(\Id \ot P_{a_1} G_{g_2}) \ket{\psi}$ with
	$(\Id \ot G_{g_2} P_{a_1}) \ket{\psi}$, and each summand on the right is the
	overlap of $(G_{g_2} \ot P_{a_1}) \ket{\psi}$ with the same vector. The
	difference of the two left vectors is the first family applied on the second
	factor to the difference of the two placements of the second family, so the
	Cauchy--Schwarz inequality over the pairs $(a_1, g_2)$ bounds the gap by the
	product of two square roots. The effects of a measurement placed on one
	factor contract total squared norm, so the first factor is at most the
	summed squared distance between the two placements of the second family, and
	the second factor is at most $\|\psi\|^2 = 1$.
\end{proof}

\begin{lemma}[Formalization support for Lemma~\ref{lem:pasting}]
	\label{lem:pasting-commutator-expansion}
	\lean{MIPStarRE.QPBT.commutator_mass_eq_expansion}
	\leanok
	\uses{def:pasting-tensor-placement}
	Let $P_{a_1}$ be a measurement and $G_{g_2}$ a projective measurement, both
	placed on the second tensor factor. Then
	\[
		\sum_{a_1, g_2} \bigl\| (\Id \ot [P_{a_1}, G_{g_2}]) \ket{\psi} \bigr\|^2
		= \sum_{a_1, g_2} \bigl\| (\Id \ot P_{a_1} G_{g_2}) \ket{\psi} \bigr\|^2
			+ \operatorname{Re}\sum_{a_1} \bra{\psi} \Id \ot P_{a_1}^2 \ket{\psi}
			- 2 \operatorname{Re}\sum_{a_1, g_2}
				\bra{\psi} \Id \ot G_{g_2} P_{a_1} G_{g_2} P_{a_1}
				\ket{\psi}\,.
	\]
\end{lemma}
\begin{proof}
	\leanok
	\uses{def:pasting-tensor-placement}
	Expand the squared norm of a difference at each pair: it is the sum of the
	two squared norms minus twice the real part of the overlap of the two
	vectors. The second squared norm is the expectation of
	$P_{a_1} G_{g_2} P_{a_1}$, the second family being idempotent, and summing
	over the codewords replaces the codeword effect by the identity, which
	leaves the expectation of $P_{a_1}^2$. The overlap of the two vectors is the
	expectation of $G_{g_2} P_{a_1} G_{g_2} P_{a_1}$, the effects of a
	measurement being self-adjoint.
\end{proof}

\begin{lemma}[Formalization support for Lemma~\ref{lem:pasting}]
	\label{lem:pasting-ordered-product-mass}
	\lean{MIPStarRE.QPBT.sum_norm_ordered_product_le_one}
	\leanok
	\uses{def:pasting-tensor-placement}
	Let $P_{a_1}$ and $G_{g_2}$ be measurements placed on the second tensor
	factor and let $\ket{\psi}$ be a unit vector. Then
	\[
		\sum_{a_1, g_2} \bigl\| (\Id \ot P_{a_1} G_{g_2}) \ket{\psi} \bigr\|^2
			\le 1\,.
	\]
\end{lemma}
\begin{proof}
	\leanok
	\uses{def:pasting-tensor-placement}
	The effects of a measurement placed on one tensor factor contract total
	squared norm, their squares summing to at most the identity. Applying this
	to the first family at each fixed codeword bounds the inner sum by the
	squared norm of the codeword vector, and applying it to the second family
	bounds the remaining sum by $\|\psi\|^2 = 1$.
\end{proof}

\begin{lemma}[Formalization support for Lemma~\ref{lem:pasting}]
	\label{lem:pasting-ordered-product-mass-lower}
	\lean{MIPStarRE.QPBT.mass_ordered_product_ge}
	\leanok
	\uses{def:pasting-tensor-placement, def:povm-distance}
	Let $P_{a_1}$ and $Q_{a_2}$ be measurements placed on the second tensor
	factor, with $Q$ projective, let $A_{a_1}$ be a projective measurement
	placed on the first tensor factor, all three depending on a question drawn
	from a distribution, and let $\ket{\psi}$ be a unit vector. If the averaged
	squared distance between $A_{a_1} \ot \Id$ and $\Id \ot P_{a_1}$ is at most
	$d$ and the averaged mass of the commutators $[P_{a_1}, Q_{a_2}]$ placed on
	the second factor is at most $K$, then the averaged mass of the ordered
	products satisfies
	\[
		\Exp \sum_{a_1, a_2}
			\bigl\| (\Id \ot P_{a_1} Q_{a_2}) \ket{\psi} \bigr\|^2
			\ge 1 - 2\sqrt{d} - d - 2\sqrt{K} - K\,.
	\]
\end{lemma}
\begin{proof}
	\leanok
	\uses{def:pasting-tensor-placement, def:povm-distance}
	A projective measurement placed on one tensor factor carries the whole mass
	of the state, so the first family has mass at least $1 - 2\sqrt{d} - d$ by
	the perturbation estimate for the total mass of a finite family of vectors.
	Placing the second family, projective and complete, to the left of the first
	one preserves that mass. Restoring the order of the two placements changes
	each vector by the corresponding commutator, and the same perturbation
	estimate costs a further $2\sqrt{K} + K$. The averages of the square roots
	are bounded by the square roots of the averages.
\end{proof}

